with flagged as (select *, case when lag(started_at) over (partition by customer_id order by started_at, id) is null or started_at > lag(started_at) over (partition by customer_id order by started_at, id) + interval '7' day then 1 else 0 end as is_new_session from sessions), sessionized as (select *, sum(is_new_session) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as island_id from flagged) select date_trunc('quarter', started_at) as quarter_start, customer_id, sum(island_id) as total_island_id, count_if(browser = 'Chrome') as chrome_events from sessionized group by date_trunc('quarter', started_at), customer_id order by customer_id desc
